<?php
namespace qqworld_collector\module\collect_item; use qqworld_collector\lib; class post_content extends lib { var $log_id = 'collection-project'; var $guid; var $smart_paging; var $comp_same = 0; public function init() { add_filter( 'qqworld-collector-collecting-engine-collect-item-' . $this->guid, array($this, 'filter'), 10, 7 ); add_filter( 'qqworld-collector-collecting-engine-collect-item-after-filter-' . $this->guid, array($this, 'filter_after'), 10, 6 ); } public function pseudo_original($content) { $dom = new \DOMDocument('1.0', 'utf-8'); libxml_use_internal_errors(true); $dom->loadHTML('<meta http-equiv="Content-Type" content="text/html;charset=utf-8">' . $content); $body = $dom->getElementsByTagName('body'); $paragraphs = array(); foreach ($body[0]->childNodes as $childNode) { $paragraphs[] = $childNode->ownerDocument->saveHTML($childNode); } $paragraphs = array_filter($paragraphs, function($v) { return trim($v); }); if (count($paragraphs)) { shuffle($paragraphs); $content = implode("\n", $paragraphs); } libxml_clear_errors(); return $content; } public function get_same_str_arr($url_1, $url_2) { if (empty($url_1) || empty($url_2)) return false; $url_1 = str_split(urldecode($url_1)); $url_2 = str_split(urldecode($url_2)); $resutls = array(); foreach ($url_1 as $index => $str) { if ($str == $url_2[$index]) $resutls[$index] = $str; else break; } return implode('', $resutls); } public function get_pagenate($pages, $args, $html, $source_link, $download_args, $interval) { set_time_limit($this->options->qc_stress_timeout); if ($args['value']) { $preg = preg_match('/^\{filter:(.*?)\}$/i', $args['value'], $march); if ($preg) { $paging = apply_filters($march[1], array(), $html); } else { $paging = $this->core->parse_html($html, $args); } if (is_array($paging)) $paging = array_filter($paging, function($v, $k) { return !preg_match('/^#/', $v); }, ARRAY_FILTER_USE_BOTH); if ($this->smart_paging) { $results = array(); foreach ($paging as $page) { if (strstr($page, 'all') !== false) continue; $page = apply_filters( 'qqworld-collector-convert-relative-url-to-absolute-url', $page, $source_link ); $url_1 = preg_replace('/^https?:/i', '', $source_link); $url_2 = preg_replace('/^https?:/i', '', $page); if ($url_1 == $url_2) continue; $same = $this->get_same_str_arr($url_1, $url_2); if ($same) { if (!$this->comp_same) $this->comp_same = strlen($same); if ($this->comp_same<=strlen($same)) $results[$page] = $same; } } foreach ($results as $url_1 => $result_1) { foreach ($results as $url_2 => $result_2) { if (strlen($result_1) > strlen($result_2)) { unset($results[$url_2]); } } } if (!empty($results)) $paging = array_keys($results); else $paging = false; } } else { $paging = array($source_link); } if ($paging) { $comp_paging = $paging; foreach ($comp_paging as &$page) { $page = preg_replace('/^https?/i', '', $page); } $new_comp_paging = array_unique($comp_paging); $diff = array_diff_assoc($comp_paging, $new_comp_paging); foreach ($diff as $index => $val) { unset($paging[$index]); } foreach ($paging as $page) { $page = apply_filters( 'qqworld-collector-convert-relative-url-to-absolute-url', $page, $source_link ); if (!isset($pages[$page])) { $html = apply_filters( 'qqworld-collector-download-from-url', $page, $download_args ); sleep($interval); $html = $html['file']; $pages[$page] = $html; $pages = $this->get_pagenate($pages, $args, $html, $source_link, $download_args, $interval); } } } return $pages; } public function add_more($content) { if (strstr('<!--more-->', $content) === false) { $lines = explode("\n", $content); $lines = array_filter($lines, function($v) { return trim(strip_tags($v)); }); if (count($lines) > 1) { $key = array_shift($lines); $pos = strpos($content, $key) + strlen($key); $content = substr_replace($content, '<!--more-->', $pos, 0); } } return $content; } public function filter($items, $args, $source_link, $html, $download_args, $settings, $mode) { $template = isset($args['template']) ? $args['template'] : array(); $header = isset($template['header']) ? $template['header'] : array(); $footer = isset($template['footer']) ? $template['footer'] : array(); $paging = isset($args['paging']) ? filter_var($args['paging'], FILTER_VALIDATE_BOOLEAN) : true; $pseudo_original = isset($args['pseudo-original']) ? filter_var($args['pseudo-original'], FILTER_VALIDATE_BOOLEAN) : false; $lazyload = isset($args['lazyload']) ? $args['lazyload'] : ''; $wipe = isset($args['wipe']) ? $args['wipe'] : array(); $wipe_script = isset($wipe['script']) ? filter_var($wipe['script'], FILTER_VALIDATE_BOOLEAN) : 1; $wipe_style = isset($wipe['style']) ? filter_var($wipe['style'], FILTER_VALIDATE_BOOLEAN) : 1; $wipe_tag_comment = isset($wipe['tag-comment']) ? filter_var($wipe['tag-comment'], FILTER_VALIDATE_BOOLEAN) : 1; $wipe_empty_tags = isset($wipe['empty-tags']) ? filter_var($wipe['empty-tags'], FILTER_VALIDATE_BOOLEAN) : 1; $wipe_links = isset($wipe['links']) ? filter_var($wipe['links'], FILTER_VALIDATE_BOOLEAN) : 1; if (isset($args['paginate']) && !empty($args['paginate']['value'])) { $interval = isset($settings['interval']) ? $settings['interval'] : 0; $this->smart_paging = filter_var($args['smart-paging'], FILTER_VALIDATE_BOOLEAN); $paginate = $args['paginate']; $pages = array( $source_link => $html ); $this->comp_same = 0; $pages = $this->get_pagenate($pages, $paginate, $html, $source_link, $download_args, $interval); if (!empty($pages)) { do_action( 'qqworld-collector-log', $this->log_id, 'Post content have pages:', print_r($pages, true) ); foreach ($pages as $url => $page) { $content = $this->core->parse_html($page, $args); if (!empty($content)) { $items = array_merge($items, $content); } } } } if (empty($items)) $items = $this->core->parse_html($html, $args); if (!empty($items)) { $items = array_filter($items, array($this, 'is_not_empty')); foreach ($items as &$item) { if ($pseudo_original) $item = $this->pseudo_original($item); } $nextpage = $paging ? '<!--nextpage-->' : ''; $items = implode($nextpage, $items); $items = explode("\n", $items); $allow_trim = true; foreach ($items as &$item) { if ($allow_trim) $item = trim($item); if (strstr($item, '<pre>') !== false) $allow_trim = false; if (strstr($item, '</pre>') !== false) $allow_trim = true; } $items = array_filter($items, function($v) { return trim($v); }); $items = implode("\n", $items); $patterns = array(); $replacements = array(); if ( apply_filters('qqworld-collector-wipe-script-from-post-content', $wipe_script) ) { $patterns[] = '/<script[^>]*?>[\s\S]*?<\/script>/i'; $replacements[] = ''; $patterns[] = '/<noscript>[\s\S]*?<\/noscript>/i'; $replacements[] = ''; } if ( apply_filters('qqworld-collector-wipe-style-from-post-content', $wipe_style) ) { $patterns[] = '/<style[^>]*?>[\s\S]*?<\/style>/i'; $replacements[] = ''; $patterns[] = '/ (bgcolor|color|style)="[^"]*?"/i'; $replacements[] = ''; $patterns[] = '/ (bgcolor|color|style)=\'[^\']*?\'/i'; $replacements[] = ''; } if ( apply_filters('qqworld-collector-wipe-tag-comment-from-post-content', $wipe_tag_comment) ) { $items = preg_replace_callback('/<!--([\s\S]*?)-->/i', function($matches) { return $matches[1] == 'nextpage' ? $matches[0] : ''; }, $items); } if ( apply_filters('qqworld-collector-wipe-empty-tags-from-post-content', $wipe_empty_tags) ) $items = $this->wipe_empty_tags($items); if ( apply_filters('qqworld-collector-wipe-links-from-post-content', $wipe_links) ) { $patterns[] = '/<a[^>]*?>|<\/a>/i'; $replacements[] = ''; } if (!empty($patterns)) $items = preg_replace($patterns, $replacements, $items); if ($lazyload) { $pattern = $this->encode_pattern($lazyload); $preg = preg_match_all('/<(img|iframe)[\s\S]*?>/i', $items, $matches); if ($preg) { foreach ($matches[0] as $match) { if (preg_match('/ '.$pattern.'="/i', $match)) { $replacement = preg_replace('/ src="[\s\S]*?"/i', '', $match); $replacement = preg_replace('/ '.$pattern.'="/i', ' src="', $replacement); $items = str_replace($match, $replacement, $items); } } } } } return $items; } public function filter_after($items, $args, $source_link, $html, $settings, $mode) { if (!empty($items)) { $more = isset($args['more']) ? filter_var($args['more'], FILTER_VALIDATE_BOOLEAN) : 1; if ($more) $items = $this->add_more($items); $items = str_replace('<!--nextpage--><!--nextpage-->', '<!--nextpage-->', $items); $items = preg_replace('/<\!--nextpage-->$/', '', $items); } return $items; } } ?>